/**
 * How a value leaving this service is written as JSON: a route answer, an event, a
 * job or queue message, a peer or extern request, a cached response.
 *
 * Auto-generated by cruftfree-codegen-typescript. Do not edit manually.
 *
 * `JSON.stringify` alone writes a `Buffer` through `Buffer.prototype.toJSON` as
 * `{"type":"Buffer","data":[...]}`, a form no other target reads. A `Bytes` value
 * inside a JSON document travels as one declared text form on every target.
 */

/**
 * The `JSON.stringify` replacer writing a `Bytes` value in its declared JSON form.
 *
 * `toJSON` has already run when a replacer is called, so `value` is the `Buffer`'s
 * object form; the holder's own member is the `Buffer` itself.
 */
export function wireJsonReplacer(this: unknown, key: string, value: unknown): unknown {
  const held = (this as Record<string, unknown>)[key];
  return Buffer.isBuffer(held) ? held.toString("base64") : value;
}

/**
 * Where the `Bytes` values sit in a JSON document a declared type describes: the `Bytes`
 * itself, an array's element shape, a map's value shape, or a named struct whose members
 * are listed in a `WireStructShapes` table (only the members that hold a `Bytes`).
 */
export type WireShape =
  | 'bytes'
  | { readonly array: WireShape }
  | { readonly map: WireShape }
  | { readonly struct: string };

/** The members of each named struct that hold a `Bytes`, by wire name. */
export type WireStructShapes = Readonly<Record<string, Readonly<Record<string, WireShape>>>>;

/** The grammar of a `Bytes` value's JSON form: standard padded base64 text. */
const BYTES_JSON_FORM = new RegExp("^(?:(?:[+/-9A-Za-z]{4})+|[+/-9A-Za-z]{3}(?:[+/-9A-Za-z]{4})*=|[+/-9A-Za-z]{2}(?:[+/-9A-Za-z]{4})*==)$", "u");

/**
 * Read the `Bytes` values of the parsed JSON `value` from their JSON form into `Buffer`s.
 *
 * `JSON.parse` leaves a `Bytes` as its base64 text; the declared type says it is a `Buffer`.
 * Text that is not standard padded base64, and a value of another kind, is refused.
 *
 * @throws Error when a `Bytes` position holds anything but base64 text, or a container
 *   position holds a value of another kind.
 */
export function readWireJson(value: unknown, shape: WireShape, structs: WireStructShapes): unknown {
  if (value === null || value === undefined) {
    return value;
  }
  if (shape === 'bytes') {
    if (typeof value === 'string' && (value === '' || BYTES_JSON_FORM.test(value))) {
      return Buffer.from(value, "base64");
    }
    throw new Error('a Bytes value must be RFC 4648 standard base64 text, padded');
  }
  if ('array' in shape) {
    if (!Array.isArray(value)) {
      throw new Error('an array was expected');
    }
    return value.map((item: unknown) => readWireJson(item, shape.array, structs));
  }
  if (typeof value !== 'object' || Array.isArray(value)) {
    throw new Error('an object was expected');
  }
  const source = value as Record<string, unknown>;
  if ('map' in shape) {
    return Object.fromEntries(Object.entries(source).map(([key, item]) => [key, readWireJson(item, shape.map, structs)]));
  }
  const read: Record<string, unknown> = { ...source };
  for (const [member, memberShape] of Object.entries(structs[shape.struct] ?? {})) {
    if (member in source) {
      read[member] = readWireJson(source[member], memberShape, structs);
    }
  }
  return read;
}
